     rs=self.readstate(c,w['id'],u['id']); return self.sendj(200,{'workspace':ws(w),'channels':chans,'read_state':rs})
    m=re.match(r'/api/channels/(\d+)(?:/(.*))?$',p)
    if m:
     ch=row(c,'select * from channels where id=?',(m[1],))
