     arr=[msgobj(c,x) for x in c.execute('select * from messages where parent_id=? and deleted=0 order by id',(m[1],))]; a,n=paginate(arr,q.get('limit',[None])[0],q.get('cursor',[None])[0]); return self.sendj(200,{'replies':a,'next_cursor':n})
    if p=='/api/search':
     text=q.get('q',[''])[0]; arr=[msgobj(c,x) for x in c.execute("select m.* from messages m join channels ch on ch.id=m.channel_id where m.deleted=0 and m.body like ? order by m.id desc",('%'+text+'%',)) if accessible(c,row(c,'select * from channels where id=?',(x['channel_id'],)),u)]
