 def readstate(self,c,wid,uid,cid=None):
  chans=[cid] if cid else [x['id'] for x in c.execute('select id from channels where workspace_id=?',(wid,))]
  last=max([row(c,'select coalesce(last_read,0) n from reads where channel_id=? and user_id=?',(x,uid))['n'] if row(c,'select coalesce(last_read,0) n from reads where channel_id=? and user_id=?',(x,uid)) else 0 for x in chans] or [0])
  unread=mentions=0
  for x in chans:
   r=row(c,'select coalesce(last_read,0) n from reads where channel_id=? and user_id=?',(x,uid)); z=r['n'] if r else 0
   for e in c.execute('select event_id,data from events where channel_id=? and event_id>?',(x,z)):
    d=json.loads(e['data']); mid=d.get('message',{}).get('id')
